  "tool-subagent-fork",
  "tool-subagent-report",
  "tool-workflow",
  "tool-todo",
  "tool-goal",
  "tool-ralph",
  "tool-web",
  // service rows only the disabled tools consume
  "skill",
  "skill-filesystem",
  "skill-badge",
  "subagent",
  "subagent-spawn-in-process",
